32	// Each command's release tier decides where it shows in `--help`:
33	//   Release -- the finished, user-facing product surface (always listed).
34	//   Dev     -- developer tooling, listed only when ANDESIM_DEV is set.
35	//   Hidden  -- a stable dispatch slot for an unfinished ROADMAP feature; never
36	//              listed (explicit invocation still hits the "not yet implemented"
37	//              stub), so the product never advertises half-built work.
38	enum class Tier { Release, Dev, Hidden };
39	
40	struct Subcommand {
41	  std::string_view name;
42	  std::string_view brief;
43	  Tier tier;
44	};
45	
46	// The full command surface. Names are fixed from F0 so usage, dispatch, and
47	// tests are stable; handlers arrive feature by feature. The tier (above) keeps
48	// dev and unfinished commands out of the release `--help` (see print_usage).
49	// Listed release-first, then dev, then hidden -- dispatch is by name, so the
50	// order is purely the display order.
51	constexpr Subcommand kSubcommands[] = {
52	    {"run", "run one simulation (--mode fast|cycle|hybrid)", Tier::Release},
53	    {"list", "list models|engines", Tier::Release},
54	    {"doctor", "check environment health", Tier::Release},
55	    {"build", "build artifacts (qemu, vsim, plugin, simpoint, fixtures, driver)",
56	     Tier::Dev},
57	    {"test", "run the end-to-end suite", Tier::Dev},
58	    {"state-diff", "compare two drained state files (oracle vs vsim)",
59	     Tier::Dev},
60	    {"profile", "profile a workload into a basic-block vector", Tier::Hidden},
61	    {"cluster", "cluster a BBV into SimPoint phases", Tier::Hidden},
62	    {"archive", "snapshot a drained state into a replayable dir", Tier::Hidden},
63	    {"replay", "replay a snapshot", Tier::Hidden},
64	    {"estimate",
65	     "whole-program cycle estimate (run --mode hybrid --trigger simpoint)",
66	     Tier::Hidden},
67	};
68	
69	const Subcommand* find(std::string_view name) {
70	  for (const Subcommand& s : kSubcommands)
71	    if (s.name == name) return &s;
72	  return nullptr;
73	}
74	
75	void print_command(std::FILE* out, const Subcommand& s) {
76	  std::fprintf(out, "  %-9.*s  %.*s\n", static_cast<int>(s.name.size()),
77	               s.name.data(), static_cast<int>(s.brief.size()), s.brief.data());
78	}
79	
80	void print_usage(std::FILE* out) {
81	  std::fputs("usage: andesim <cmd> [args...]\n\n", out);
82	  std::fputs("Multi-engine driver for the Andes simulators (QEMU + vsim).\n\n",
83	             out);
84	  std::fputs("commands:\n", out);
85	  for (const Subcommand& s : kSubcommands)
86	    if (s.tier == Tier::Release) print_command(out, s);
87	
88	  if (is_dev_mode()) {
89	    std::fputs("\ndeveloper commands:\n", out);
90	    for (const Subcommand& s : kSubcommands)
91	      if (s.tier == Tier::Dev) print_command(out, s);
92	  } else {
93	    std::fputs("\n(set ANDESIM_DEV=1 to show developer commands)\n", out);
94	  }
95	}
96	
97	void print_subcommand_help(const Subcommand& sc, std::FILE* out) {
98	  std::fprintf(out, "usage: andesim %.*s [args...]\n\n",
99	               static_cast<int>(sc.name.size()), sc.name.data());
100	  std::fprintf(out, "%.*s\n", static_cast<int>(sc.brief.size()), sc.brief.data());
101	  if (sc.name == "run") {
102	    std::fputs(
103	        "\nselection:\n"
104	        "  --mode fast|cycle|hybrid          which composition to run\n"
105	        "  --engine <id>                      pick a specific engine "
106	        "(e.g. vsim:ax45mpv_premium)\n"
107	        "  --trigger marker|pc                ROI delimiter (hybrid only)\n"
108	        "  --mem-size <spec>                  guest memory, e.g. 256M / 2G "
109	        "(max 2G; fast/hybrid)\n"
110	        "  --verify                           cross-check the run against a "
111	        "QEMU oracle (hybrid)\n"
112	        "  --gdb                              pause at startup for a debugger "
113	        "(fast: QEMU stub :1234; cycle: vsim JTAG :9104 + $ICEMAN; not hybrid)\n"
114	        "  --gdb-port <port>                  override the --gdb port "
115	        "(fast default 1234, cycle 9104)\n",
116	        out);
117	    // Dev-only knobs, hidden from the release surface like the Dev commands.
118	    if (is_dev_mode())
119	      std::fputs(
120	          "  --cosim                            co-sim vs the QEMU oracle: "
121	          "hybrid (ROI checkpoints) or cycle (lock-step)\n"
122	          "  --cosim-interval <N>               hybrid: checkpoint every N "
123	          "retired insns (default 10000)\n"
124	          "  --cosim-refine                     hybrid: narrow the diverging "
125	          "window ~16x/pass toward the instruction\n"
126	          "  --cosim-max-records <K>            cycle lock-step: stop after K "
127	          "per-attempt records (0 = until exit)\n"
128	          "  --pc-start <sym|0x>                cycle lock-step: arm pc "
129	          "(default: the ELF entry)\n",
130	          out);
131	    std::fputs(
